import type {WorkspaceSql} from '../../packages/neuvetra-database/src/workspace'
import {auditLegacyStagingExposure} from '../../packages/neuvetra-database/src/staging-audit'
import {canonicalReceipts,inventory,lockedTables,sameRows,sameCatalog,requireValue,MIGRATION,MIGRATION_NAME,NEW_TABLES,runtimeSafe,type Inventory} from './m73-common'
import {hashManifestValue} from './create-source-manifest'
/** Caller must use a transaction; injection permits native offline verification only. */
export async function applyExact16(tx:WorkspaceSql,baseline:Inventory){
  await tx.query('select pg_advisory_xact_lock(630009)')
  await lockedTables(tx)
  const manifest=await canonicalReceipts(tx,15)
  await runtimeSafe(tx)
  requireValue((await auditLegacyStagingExposure(tx)).legacyContainmentVerified)
  const before=await inventory(tx)
  requireValue(hashManifestValue(before)===hashManifestValue(baseline))
  requireValue(/^[a-f0-9]{64}$/.test(MIGRATION)&&manifest.length===16&&manifest[15]?.name===MIGRATION_NAME&&manifest[15]?.sha256===MIGRATION)
  await tx.exec(manifest[15]!.sql)
  await tx.query('insert into neuvetra.schema_migrations(name,sha256) values($1,$2)',[manifest[15]!.name,MIGRATION])
  await canonicalReceipts(tx,16)
  await runtimeSafe(tx)
  const after=await inventory(tx)
  sameRows(before,after,true)
  sameCatalog(before,after,true)
  // No old row may change, including duplicate multiplicity. Only one new migration receipt is expected.
  for(const old of before.tables){const now=after.tables.find(t=>t.name===old.name)!;requireValue(now.count===old.count+(old.name==='schema_migrations'?1:0))}
  requireValue(after.tables.length===before.tables.length+NEW_TABLES.length&&NEW_TABLES.every(name=>!before.tables.some(t=>t.name===name)&&after.tables.some(t=>t.name===name&&t.count===0)))
  requireValue(hashManifestValue(before.roles)===hashManifestValue(after.roles)&&hashManifestValue(before.memberships)===hashManifestValue(after.memberships)&&hashManifestValue(before.defaultAcls)===hashManifestValue(after.defaultAcls))
  requireValue((await auditLegacyStagingExposure(tx)).legacyContainmentVerified)
  return {before,after}
}

/** JSON stdin {operatorDatabaseUrl}; args pg_dump.exe archive.dpapi receipt.json. */
import {connectOperator,operatorUrl,canonicalReceipts,inventory,exclusiveJson,sha,requireValue,PROJECT,runtimeSafe} from './m73-common'
import {resolve} from 'node:path'
export async function createApplicationBundle(db:Awaited<ReturnType<typeof connectOperator>>,pgDump:string,env:Record<string,string|undefined>){
 return db.transaction(async tx=>{
  await tx.exec('set transaction isolation level repeatable read read only');await canonicalReceipts(tx,15);await runtimeSafe(tx)
  // Exported snapshot binds dump, fingerprints and dependencies to the same MVCC state.
  const snapshot=(await tx.query<{snapshot:string}>('select pg_export_snapshot() snapshot')).rows[0]!.snapshot
  const baseline=await inventory(tx)
  requireValue(baseline.dependencies.every(d=>d.schema==='auth'&&d.relation==='users'))
  const refs=(await tx.query<{table_name:string;column_name:string}>("select c.relname table_name,a.attname column_name from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum=k.conkey[1] where n.nspname='neuvetra' and k.contype='f' and k.confrelid='auth.users'::regclass and cardinality(k.conkey)=1 order by 1,2")).rows
  requireValue(refs.length&&refs.every(r=>/^[a-z_]+$/.test(r.table_name)&&/^[a-z_]+$/.test(r.column_name)))
  const subjects=(await tx.query<{id:string}>('select distinct id from ('+refs.map(r=>`select ${r.column_name} id from neuvetra.${r.table_name}`).join(' union all ')+') u where id is not null order by id')).rows.map(r=>r.id)
  requireValue(subjects.every(id=>/^[0-9a-f-]{36}$/.test(id)))
  const uid=(await tx.query<{definition:string}>("select pg_get_functiondef('auth.uid()'::regprocedure) definition")).rows[0]!.definition
  const child=Bun.spawn([pgDump,'--format=custom','--no-password','--schema=neuvetra','--snapshot='+snapshot],{env,stdout:'pipe',stderr:'pipe'})
  const [dump,,code]=await Promise.all([new Response(child.stdout).arrayBuffer(),new Response(child.stderr).text(),child.exited]);requireValue(code===0&&dump.byteLength>16)
  return {profile:'neuvetra.m73.application-recovery.v1',project:PROJECT,createdAt:new Date().toISOString(),schemaVersion:15,inventory:baseline,dependencies:{authUserIds:subjects,authUidDefinition:uid,providerRecovery:'excluded: users are UUID dependency stubs only; no credentials, sessions, provider configuration or storage objects'},dumpSha256:sha(new Uint8Array(dump)),dumpBase64:Buffer.from(dump).toString('base64')}
 })
}
async function main(){
let db:Awaited<ReturnType<typeof connectOperator>>|undefined,stage='configuration'
try{
 const [pgDump,archive,receipt]=process.argv.slice(2);requireValue(pgDump&&archive&&receipt&&!await Bun.file(archive).exists()&&!await Bun.file(receipt).exists())
 const input=JSON.parse(await Bun.stdin.text()),url=operatorUrl(input.operatorDatabaseUrl)
 const env=Object.fromEntries(Object.entries(process.env).filter(([key])=>!key.toUpperCase().startsWith('PG')))
 Object.assign(env,{PGHOST:url.hostname,PGPORT:url.port,PGDATABASE:'postgres',PGUSER:decodeURIComponent(url.username),PGPASSWORD:decodeURIComponent(url.password),PGSSLMODE:'verify-full',PGSSLROOTCERT:resolve('tools/cloud/fixtures/supabase-prod-ca-2021.crt'),PGCONNECT_TIMEOUT:'15'})
 db=await connectOperator(input.operatorDatabaseUrl)
 stage='snapshot_and_dump'
 const bundle=await createApplicationBundle(db,pgDump,env)
 stage='encrypt'
 const child=Bun.spawn(['powershell.exe','-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',resolve('tools/staging/m73-seal-backup.ps1'),'-ArchivePath',resolve(archive)],{stdin:'pipe',stdout:'pipe',stderr:'pipe'});await child.stdin.write(JSON.stringify(bundle));await child.stdin.end()
 const [sealed,,code]=await Promise.all([new Response(child.stdout).text(),new Response(child.stderr).text(),child.exited]);requireValue(code===0&&JSON.parse(sealed).status==='m73_bundle_sealed')
 stage='receipt'
 await exclusiveJson(receipt,{status:'m73_encrypted_application_backup',createdAt:bundle.createdAt,project:PROJECT,schemaVersion:15,archiveSha256:sha(new Uint8Array(await Bun.file(archive).arrayBuffer())),dumpSha256:bundle.dumpSha256,inventory:bundle.inventory,protection:'DPAPI CurrentUser; same Windows identity and profile required',scope:'neuvetra schema/data/owners/ACLs plus Auth UUID/uid dependencies; Supabase Auth/provider recovery excluded',restoreDrill:'pending'})
 console.log(JSON.stringify({status:'m73_encrypted_application_backup',schemaVersion:15,tables:bundle.inventory.tables.length}))
}catch{console.error(JSON.stringify({status:'m73_backup_failed',stage}));process.exitCode=1}finally{await db?.close()}

}
if(import.meta.main)await main()

/** Read-only role parity preflight for the existing isolated loopback55472 cluster. Never resets or modifies roles. */
import {createPostgresConnection} from '../../packages/neuvetra-database/src/hosted'
import {ROLE_SQL,MEMBERS_SQL,requireValue,exclusiveJson,sha,PROJECT} from './m73-common'
import {hashManifestValue} from './create-source-manifest'
let db:ReturnType<typeof createPostgresConnection>|undefined
try{
 const [source,output]=process.argv.slice(2);requireValue(source&&output&&!await Bun.file(output).exists())
 const bytes=await Bun.file(source).text(),receipt=JSON.parse(bytes),state=receipt.inventory
 requireValue(receipt.status==='m73_encrypted_application_backup'&&receipt.schemaVersion===15&&receipt.project===PROJECT&&Array.isArray(state.roles)&&Array.isArray(state.memberships)&&state.roles.every((r:any)=>typeof r.rolname==='string')&&!state.memberships.some((r:any)=>r.member==='neuvetra_runtime'))
 db=createPostgresConnection('postgres://supabase_admin@127.0.0.1:55472/postgres',{maxConnections:1,tls:false})
 await db.transaction(async tx=>{
  await tx.exec('set transaction isolation level repeatable read read only')
  requireValue(hashManifestValue((await tx.query(ROLE_SQL)).rows)===hashManifestValue(state.roles))
  requireValue(hashManifestValue((await tx.query(MEMBERS_SQL)).rows)===hashManifestValue(state.memberships))
 })
 await exclusiveJson(output,{status:'m73_existing_isolated_roles_exact',createdAt:new Date().toISOString(),port:55472,sourceReceiptSha256:sha(bytes),roles:state.roles.length,memberships:state.memberships.length,clusterMutated:false,passwords:'not copied; local trust on loopback only',providerConfiguration:'not restored',defaultAcls:'Restore rejects source global/application defaults; provider-schema defaults excluded'})
 console.log(JSON.stringify({status:'m73_existing_isolated_roles_exact',clusterMutated:false}))
}catch{console.error(JSON.stringify({status:'m73_isolated_role_parity_failed',clusterMutated:false}));process.exitCode=1}finally{await db?.close()}

/** Operator helpers only. No connection, secrets, or writes occur on import. */
import {open} from 'node:fs/promises'
import {createPostgresConnection} from '../../packages/neuvetra-database/src/hosted'
import {loadStagingDatabaseCa} from '../../packages/neuvetra-database/src/staging-tls'
import {readMigrationManifest} from '../../packages/neuvetra-database/src/staging-migrations'
import type {WorkspaceSql} from '../../packages/neuvetra-database/src/workspace'
import {SOURCE_METADATA_QUERIES,canonicalManifestJson,hashManifestValue} from './create-source-manifest'

export const PROJECT='icockcoguyadhryzydvl'
export const BASELINE_MANIFEST_SHA256='476fae6510167b9c30063bf442d8cd10a2def42ea2ed5d84fa23369aeada1634'
// Coordinator-supplied author candidate. Hosted execution separately requires an independent exact-byte gate.
export const MIGRATION='2f5489d37fdd59963d12e60947b8dddce34cc4e1dc4100813545b1c0dbb1c9b7'
export const MIGRATION_NAME='0016_stationary_natural_gas.sql'
export const NEW_TABLES=['stationary_gas_audit','stationary_gas_heads','stationary_gas_reports','stationary_gas_requests','stationary_gas_reviews','stationary_gas_statements','stationary_gas_versions'] as const
export const sha=(bytes:string|Uint8Array)=>new Bun.CryptoHasher('sha256').update(bytes).digest('hex')
export function requireValue(value:unknown):asserts value {if(!value)throw Error('M73 gate refused')}
export async function exclusiveJson(path:string,value:unknown){const f=await open(path,'wx',0o600);try{await f.writeFile(JSON.stringify(value,null,2)+'\n');await f.sync()}finally{await f.close()}}
export function operatorUrl(value:string){const u=new URL(value);requireValue(['postgres:','postgresql:'].includes(u.protocol)&&u.hostname==='aws-1-us-west-1.pooler.supabase.com'&&u.port==='5432'&&decodeURIComponent(u.username)==='postgres.'+PROJECT&&u.pathname==='/postgres'&&u.password&&!u.hash);u.search='';return u}
export async function connectOperator(value:string){const u=operatorUrl(value);return createPostgresConnection(u.toString(),{maxConnections:1,tlsCaPem:await loadStagingDatabaseCa({caFile:'tools/cloud/fixtures/supabase-prod-ca-2021.crt'})})}
export function connectLocal(name:string,port=55463){requireValue(/^m73_(ops|qa|security)_[a-z0-9_]+$/.test(name)&&[55463,55472].includes(port));return createPostgresConnection(`postgres://${port===55472?'supabase_admin':'m63_test_admin'}@127.0.0.1:${port}/`+name,{maxConnections:1,tls:false})}
export async function canonicalReceipts(tx:WorkspaceSql,version:15|16){
 const manifest=await readMigrationManifest()
 requireValue((manifest.length===15||manifest.length===16)&&hashManifestValue(manifest.slice(0,15).map(({name,sha256})=>({name,sha256})))===BASELINE_MANIFEST_SHA256)
 if(version===16)requireValue(/^[a-f0-9]{64}$/.test(MIGRATION)&&manifest.length===16&&manifest[15]?.name===MIGRATION_NAME&&manifest[15]?.sha256===MIGRATION)
 const receipts=(await tx.query<{name:string;sha256:string}>('select name,sha256 from neuvetra.schema_migrations order by name')).rows
 requireValue(receipts.length===version&&receipts.every((r,i)=>r.name===manifest[i]?.name&&r.sha256===manifest[i]?.sha256))
 const target=(await tx.query<{project_ref:string;profile:string}>('select project_ref,profile from neuvetra.staging_target')).rows
 requireValue(target.length===1&&target[0]?.project_ref===PROJECT&&target[0]?.profile==='neuvetra.private-synthetic-staging.v1')
 return manifest
}
export const ROLE_SQL="select rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolbypassrls from pg_roles where rolname !~ '^pg_' order by rolname"
export const MEMBERS_SQL="select pg_get_userbyid(roleid) role,pg_get_userbyid(member) member,pg_get_userbyid(grantor) grantor,admin_option,inherit_option,set_option from pg_auth_members order by 1,2,3"
export const DEFAULT_SQL="select pg_get_userbyid(d.defaclrole) owner,coalesce(n.nspname,'*') schema,d.defaclobjtype kind,d.defaclacl::text acl from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace order by 1,2,3"
// Compare effective ACL semantics: pg_restore may encode explicit owner-only ACLs as NULL defaults.
const effectiveAcl=(column:string,owner:string,kind:string)=>`(select jsonb_agg(jsonb_build_object('grantee',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) order by case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable) from aclexplode(coalesce(${column},acldefault('${kind}',${owner}))) a)`
const CATALOG_QUERIES={...SOURCE_METADATA_QUERIES,
 tables:`select c.relname,pg_get_userbyid(c.relowner) owner,c.relrowsecurity,c.relforcerowsecurity,${effectiveAcl('c.relacl','c.relowner','r')} acl from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='neuvetra' and c.relkind='r' order by c.relname`,
 functions:`select p.oid::regprocedure::text signature,pg_get_userbyid(p.proowner) owner,p.prosecdef,p.proconfig,${effectiveAcl('p.proacl','p.proowner','f')} acl,pg_get_functiondef(p.oid) definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='neuvetra' order by signature`,
 schema:`select nspname,pg_get_userbyid(nspowner) owner,${effectiveAcl('nspacl','nspowner','n')} acl from pg_namespace where nspname='neuvetra'`
}
export async function inventory(tx:WorkspaceSql){
 const privilege=(await tx.query<{safe:boolean}>("select (rolsuper or rolbypassrls) safe from pg_roles where rolname=current_user")).rows;requireValue(privilege[0]?.safe===true)
 const tables=(await tx.query<{name:string}>("select c.relname name from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='neuvetra' and c.relkind='r' order by 1")).rows
 requireValue(tables.length>0&&tables.every(t=>/^[a-z_]+$/.test(t.name)))
 const rows=[]
 for(const {name}of tables){const values=(await tx.query<{value:unknown}>(`select to_jsonb(t) value from neuvetra.${name} t`)).rows.map(r=>r.value).sort((a,b)=>canonicalManifestJson(a).localeCompare(canonicalManifestJson(b)));rows.push({name,count:values.length,sha256:hashManifestValue(values),rowHashes:values.map(hashManifestValue).sort()})}
 const metadata:Record<string,string>={},catalogRowHashes:Record<string,string[]>={}
 for(const [key,sql]of Object.entries({...CATALOG_QUERIES,
  constraints:"select c.relname table_name,k.conname,pg_get_constraintdef(k.oid) definition from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='neuvetra' order by 1,2",
  indexes:"select tablename,indexname,indexdef from pg_indexes where schemaname='neuvetra' order by 1,2",
  triggers:"select c.relname table_name,t.tgname,pg_get_triggerdef(t.oid) definition,t.tgenabled from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='neuvetra' and not t.tgisinternal order by 1,2",
  columns:"select table_name,column_name,ordinal_position,column_default,is_nullable,data_type,udt_schema,udt_name,character_maximum_length,numeric_precision,numeric_scale,is_identity,is_generated,generation_expression,collation_name from information_schema.columns where table_schema='neuvetra' order by table_name,ordinal_position"
 })){
  const values=(await tx.query(sql)).rows;metadata[key]=hashManifestValue(values);catalogRowHashes[key]=values.map(hashManifestValue).sort()
 }
 const roles=(await tx.query(ROLE_SQL)).rows,memberships=(await tx.query(MEMBERS_SQL)).rows,defaultAcls=(await tx.query(DEFAULT_SQL)).rows
 const dependencies=(await tx.query("select distinct rn.nspname schema,rc.relname relation from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace join pg_class rc on rc.oid=k.confrelid join pg_namespace rn on rn.oid=rc.relnamespace where n.nspname='neuvetra' and rn.nspname<>'neuvetra' order by 1,2")).rows
 return {tables:rows,metadata,catalogRowHashes,roles,memberships,defaultAcls,dependencies}
}
export type Inventory=Awaited<ReturnType<typeof inventory>>
export async function runtimeSafe(tx:WorkspaceSql){const row=(await tx.query<{safe:boolean}>(`select not r.rolsuper and not r.rolbypassrls and not r.rolcreatedb and not r.rolcreaterole and not r.rolreplication and not r.rolinherit and not exists(select 1 from pg_auth_members where member=r.oid) and not exists(select 1 from pg_namespace where nspname='neuvetra' and nspowner=r.oid) and not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='neuvetra' and p.proowner=r.oid) and not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='neuvetra' and (c.relowner=r.oid or(c.relkind='r' and(not c.relrowsecurity or not c.relforcerowsecurity)))) and not has_schema_privilege(r.rolname,'neuvetra','CREATE') and not has_schema_privilege(r.rolname,'public','CREATE') and not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='neuvetra' and c.relkind in('r','p','v','m','f') and has_table_privilege(r.rolname,c.oid,'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')) safe from pg_roles r where rolname='neuvetra_runtime'`)).rows;requireValue(row[0]?.safe===true)}
export function sameRows(before:Inventory,after:Inventory,allowAppend=false){for(const old of before.tables){const now=after.tables.find(t=>t.name===old.name);requireValue(now);if(!allowAppend)requireValue(old.sha256===now.sha256&&old.count===now.count);else{const remaining=[...now.rowHashes];for(const hash of old.rowHashes){const index=remaining.indexOf(hash);requireValue(index>=0);remaining.splice(index,1)}}}}
export async function lockedTables(tx:WorkspaceSql){const names=(await tx.query<{name:string}>("select tablename name from pg_tables where schemaname='neuvetra' order by tablename")).rows;requireValue(names.length&&names.every(t=>/^[a-z_]+$/.test(t.name)));await tx.exec('lock table '+names.map(t=>'neuvetra.'+t.name).join(',')+' in share mode')}

export function sameCatalog(before:Inventory,after:Inventory,allowAppend=false){
 requireValue(hashManifestValue(Object.keys(before.catalogRowHashes).sort())===hashManifestValue(Object.keys(after.catalogRowHashes).sort()))
 for(const [key,old] of Object.entries(before.catalogRowHashes)){
  const now=after.catalogRowHashes[key]!;if(!allowAppend){requireValue(hashManifestValue(old)===hashManifestValue(now));continue}
  const remaining=[...now];for(const h of old){const i=remaining.indexOf(h);requireValue(i>=0);remaining.splice(i,1)}
 }
}

/** Author-only native drill. Opt-in; source is read-only m71_author_release; all writes use NEW m73_ops_* clones. */
import {test,expect} from 'bun:test'
import {createPostgresConnection} from '../../packages/neuvetra-database/src/hosted'
import {readMigrationManifest} from '../../packages/neuvetra-database/src/staging-migrations'
import {planLegacyStagingContainment,auditLegacyStagingExposure} from '../../packages/neuvetra-database/src/staging-audit'
import {inventory,canonicalReceipts,sameCatalog,connectLocal,requireValue,sha,BASELINE_MANIFEST_SHA256,MIGRATION,PROJECT,exclusiveJson} from './m73-common'
import {createApplicationBundle} from './m73-backup'
import {applyExact16} from './m73-apply'
import {hashManifestValue} from './create-source-manifest'
import {mkdir} from 'node:fs/promises'
import {resolve} from 'node:path'
const native=process.env.M73_OPERATORS_NATIVE==='enabled'?test:test.skip
const pg='C:/Users/nimab/Neuvetra/m63-runtime/pgsql/bin/'
const cleanEnv=(database:string)=>({...Object.fromEntries(Object.entries(process.env).filter(([k])=>!k.toUpperCase().startsWith('PG'))),PGHOST:'127.0.0.1',PGPORT:'55463',PGDATABASE:database,PGUSER:'m63_test_admin',PGSSLMODE:'disable',PGCONNECT_TIMEOUT:'10'})
async function child(args:string[],env:Record<string,string|undefined>,input?:Uint8Array|string){
 const p=Bun.spawn(args,{env,stdin:'pipe',stdout:'pipe',stderr:'pipe'});if(input!==undefined)await p.stdin.write(input);await p.stdin.end()
 const [bytes,errorText,code]=await Promise.all([new Response(p.stdout).arrayBuffer(),new Response(p.stderr).text(),p.exited]);if(code!==0){let stage='child_failed';try{const value=JSON.parse(errorText);if(typeof value.stage==='string'&&/^[a-z_]+$/.test(value.stage))stage=value.stage}catch{}throw Error('M73 synthetic child refused: '+stage)}return new Uint8Array(bytes)
}
async function rejected(operation:()=>Promise<unknown>){let refused=false;try{await operation()}catch{refused=true}expect(refused).toBe(true)}
native('exact15 source clone, backup and actual restore; pinned16 atomic migration when available',async()=>{
 const suffix=Date.now().toString(),name='m73_ops_author_'+suffix,restoredName='m73_ops_restore_'+suffix
 const output=resolve('.tmp/m73-ops-'+suffix);await mkdir(output,{recursive:false})
 const source=createPostgresConnection('postgres://m63_test_admin@127.0.0.1:55463/m71_author_release',{tls:false,maxConnections:1})
 const admin=createPostgresConnection('postgres://m63_test_admin@127.0.0.1:55463/postgres',{tls:false,maxConnections:1})
 let db:ReturnType<typeof connectLocal>|undefined,restored:ReturnType<typeof connectLocal>|undefined
 let migrationExecuted=false,rollbackVerified=false,reapplyRejected=false
 try{
  // All source observation/dump occurs in one read-only snapshot, with exact canonical15 receipts.
  const original=await source.transaction(async tx=>{
   await tx.exec('set transaction isolation level repeatable read read only')
   const manifest=await readMigrationManifest(),receipts=(await tx.query<{name:string;sha256:string}>('select name,sha256 from neuvetra.schema_migrations order by name')).rows
   requireValue(receipts.length===15&&hashManifestValue(receipts)===BASELINE_MANIFEST_SHA256&&hashManifestValue(manifest.slice(0,15).map(({name,sha256})=>({name,sha256})))===BASELINE_MANIFEST_SHA256)
   const snapshot=(await tx.query<{snapshot:string}>('select pg_export_snapshot() snapshot')).rows[0]!.snapshot
   return {inventory:await inventory(tx),dump:await child([pg+'pg_dump.exe','--format=custom','--no-password','--schema=neuvetra','--schema=auth','--snapshot='+snapshot],cleanEnv('m71_author_release'))}
  })
  requireValue((await admin.query('select 1 from pg_database where datname=$1',[name])).rows.length===0)
  await admin.exec('create database '+name+' template template0');db=connectLocal(name)
  await child([pg+'pg_restore.exe','--exit-on-error','--single-transaction','--no-password','--dbname='+name],cleanEnv(name),original.dump)
  expect(await db.transaction(tx=>inventory(tx))).toEqual(original.inventory)
  // Authorized synthetic clone adaptation only; these are NOT observed hosted target/containment facts.
  await db.query('update neuvetra.staging_target set project_ref=$1',[PROJECT])
  const plan=await planLegacyStagingContainment(db);for(const statement of plan.statements)await db.exec(statement)
  for(const statement of plan.providerAdminStatements)await db.exec(statement)
  expect((await auditLegacyStagingExposure(db)).legacyContainmentVerified).toBe(true)
